inConversation.example:
// client
const { Hud } = kcds.ui;

if (!Hud.inConversation()) {
  Hud.showNotification('The bell rings.');
}

hudPartShown.example:
// client
if (!kcds.ui.Hud.hudPartShown('Compass')) {
  console.log('a resource hides the compass');
}

hudPartShown.exampleCs:
// client
if (!Hud.HudPartShown("Compass"))
{
    Log.Info("a resource hides the compass");
}

effectList.example:
// client
for (const effect of kcds.ui.Hud.effectList()) {
  console.log(effect.name, effect.params.map((param) => param.name).join(', '));
}

effectList.exampleCs:
// client
foreach (var effect in Hud.EffectList())
{
    Log.Info($"{effect["name"]} {string.Join(", ", effect["params"].Select(param => param["name"]).ToArray())}");
}

startEffect.example:
// client
const hurtEffect = kcds.ui.Hud.startEffect(
  'screenBlood',
  { amount: 0.6 },
  { fadeInMs: 200, durationMs: 1500, fadeOutMs: 800 },
);

changeEffect.example:
// client
const { Hud } = kcds.ui;

const blurEffect = Hud.startEffect('blur', { amount: 0.2 });
Hud.changeEffect(blurEffect, { amount: 0.6 }, { fadeMs: 2000 });

changeEffect.exampleCs:
// client

var blurEffect = Hud.StartEffect("blur", new { amount = 0.2 });
Hud.ChangeEffect(blurEffect, new { amount = 0.6 }, new { fadeMs = 2000 });

effectRunning.example:
// client
if (!kcds.ui.Hud.effectRunning(blurEffect)) {
  console.log('the blur is gone');
}

effectRunning.exampleCs:
// client
if (!Hud.EffectRunning(blurEffect))
{
    Log.Info("the blur is gone");
}

worldToScreen.example:
// client
const place = kcds.ui.Hud.worldToScreen(new kcds.math.Vector3(1652.5, 2151.5, 39));
if (place?.onScreen) {
  console.log(`at ${place.x}, ${place.y} px`);
}

worldToScreen.exampleCs:
// client
var place = Hud.WorldToScreen(new Vector3(1652.5, 2151.5, 39));
if (place["onScreen"])
{
    Log.Info($"at {place["x"]}, {place["y"]} px");
}

showTutorialHint.example:
// client
const fishingHint = kcds.ui.Hud.showTutorialHint({
  title: 'Fishing',
  text: 'Stand at the water and cast.',
  durationMs: 10000,
});

isTutorialHintShown.example:
// client
const { Hud } = kcds.ui;

if (!Hud.isTutorialHintShown()) {
  Hud.showTutorialHint({ title: 'Fishing', text: 'Stand at the water and cast.' });
}

isTutorialHintShown.exampleCs:
// client

if (!Hud.IsTutorialHintShown())
{
    Hud.ShowTutorialHint(new { title = "Fishing", text = "Stand at the water and cast." });
}

showShootingContest.example:
// client
kcds.ui.Hud.showShootingContest({
  player: { name: 'Henry', arrows: 5 },
  opponents: [{ name: 'Jindra', arrows: 5 }],
});

updateShootingContest.example:
// client: the server sends each shot's score with player.emit('archery:score', score)
kcds.core.Events.on('archery:score', (score) => {
  kcds.ui.Hud.updateShootingContest({
    player: { arrows: score.arrows, points: score.points },
    opponents: [{ arrows: score.rivalArrows, points: score.rivalPoints }],
  });
});

updateShootingContest.exampleCs:
// client: the server sends each shot's score with player.emit('archery:score', score)
Events.On("archery:score", (JsValue score) =>
{
    Hud.UpdateShootingContest(new { player = new { arrows = score["arrows"], points = score["points"] }, opponents = new object[] { new { arrows = score["rivalArrows"], points = score["rivalPoints"] } } });
});

